mapper.select:
SELECT * FROM ( SELECT ROWNUM AS rn, a.* FROM ( SELECT b.bd_id, b.m_id, m.m_nickname AS author_nickname, b.bd_category, b.bd_title, b.bd_view_count, b.recruit_status, b.pln_id, b.bd_rating, b.created_at, (SELECT COUNT(*) FROM board_comment c WHERE c.bd_id = b.bd_id AND c.is_deleted = 0) AS comment_count FROM board b LEFT JOIN member m ON b.m_id = m.m_id WHERE b.is_deleted = 0
AND b.bd_category = #{category}
AND (b.bd_title LIKE '%' || #{keyword} || '%' OR m.m_nickname LIKE '%' || #{keyword} || '%')
ORDER BY b.created_at DESC ) a WHERE ROWNUM <= #{offset} + #{size} ) WHERE rn > #{offset}

SELECT COUNT(*) FROM board b LEFT JOIN member m ON b.m_id = m.m_id WHERE b.is_deleted = 0
AND b.bd_category = #{category}
AND (b.bd_title LIKE '%' || #{keyword} || '%' OR m.m_nickname LIKE '%' || #{keyword} || '%')

mapper.update:
UPDATE board
SET bd_view_count = bd_view_count + 1
WHERE bd_id = #{bdId}
